// Fixed-step gravity, restitution, friction and planar contact impulses.
// Outcomes remain independently generated by the secure dice engine.
export function makeBodies(n,halfX,halfZ,r,random=Math.random){
const bodies=[];for(let i=0;i<n;i++){let x=0,z=0,best=-1;for(let k=0;k<100;k++){const a=(random()*2-1)*(halfX-r),c=(random()*2-1)*(halfZ-r);const d=bodies.length?Math.min(...bodies.map(b=>Math.hypot(a-b.x,c-b.z))):Infinity;if(d>best){x=a;z=c;best=d;}if(d>=2*r+.05)break;}bodies.push({x,z,y:0,vx:0,vz:0,vy:0,r,spin:0,omega:0});}return bodies;
}
export function launch(bodies,random=Math.random){for(const b of bodies){b.y=.8+random()*1.2;b.vy=1+random()*2;const a=random()*Math.PI*2;b.vx=Math.cos(a)*(2+random()*3);b.vz=Math.sin(a)*(2+random()*3);b.omega=7+random()*9;}return bodies;}
export function stepTray(bodies,dt,halfX,halfZ){for(const b of bodies){b.vy-=12*dt;b.y+=b.vy*dt;if(b.y<0){b.y=0;b.vy=Math.abs(b.vy)<.55?0:-b.vy*.36;}const damp=Math.exp(-(b.y>0?.35:3.2)*dt);b.vx*=damp;b.vz*=damp;b.omega*=Math.exp(-(b.y>0?.45:2.6)*dt);b.x+=b.vx*dt;b.z+=b.vz*dt;b.spin+=b.omega*dt;for(const [axis,vel,limit] of [['x','vx',halfX],['z','vz',halfZ]]){const bound=Math.max(0,limit-b.r);if(Math.abs(b[axis])>bound){b[axis]=Math.sign(b[axis])*bound;if(b[axis]*b[vel]>0)b[vel]*=-.55;}}}
for(let pass=0;pass<3;pass++)for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){const a=bodies[i],b=bodies[j];if(Math.abs(a.y-b.y)>a.r+b.r)continue;const dx=b.x-a.x,dz=b.z-a.z,d=Math.hypot(dx,dz),min=a.r+b.r;if(d>=min)continue;const nx=d>1e-7?dx/d:1,nz=d>1e-7?dz/d:0;const push=(min-d)*.5;a.x-=nx*push;a.z-=nz*push;b.x+=nx*push;b.z+=nz*push;const rel=(b.vx-a.vx)*nx+(b.vz-a.vz)*nz;if(rel<0){const impulse=-rel*.73;a.vx-=impulse*nx;a.vz-=impulse*nz;b.vx+=impulse*nx;b.vz+=impulse*nz;}}
for(const b of bodies){b.x=Math.max(-halfX+b.r,Math.min(halfX-b.r,b.x));b.z=Math.max(-halfZ+b.r,Math.min(halfZ-b.r,b.z));}return bodies;}
